('Highland','Scotland','Proposed £5 per room per night (tiered fixed amount)','Not set; decision due 10 Dec 2026, then 18-month lead-in','consulting',['https://www.highland.gov.uk/news/article/17462/highland-council-opens-statutory-public-consultation-on-a-tiered-fixed-amount-visitor-levy-proposal','https://www.visitscotland.org/tourism-events-industry/visitor-levy'],57.478,-4.225,'Consultation open until 30 Nov 2026.'),
('Perth & Kinross','Scotland','Reported £4 per room per night '+UV,'Not set','consulting',['https://www.pkc.gov.uk/article/24551/Perth-and-Kinross-Visitor-Levy','https://www.visitscotland.org/tourism-events-industry/visitor-levy'],56.396,-3.437,'Consultation 19 Aug to 11 Nov 2026.'),
('Dundee','Scotland','Not stated here','Not set','consulting',['https://www.visitscotland.org/tourism-events-industry/visitor-levy'],56.462,-2.970,'Consultation 31 Aug to 27 Nov 2026.'),
('Falkirk','Scotland','Not stated here','Not set','consulting',['https://www.visitscotland.org/tourism-events-industry/visitor-levy'],56.002,-3.784,'Consultation open until 25 Nov 2026.'),
('Aberdeenshire, Eilean Siar, Dumfries &amp; Galloway, East Ayrshire, Fife, Moray, Orkney, Shetland, South Ayrshire','Scotland','None proposed yet','Not set','proposed',['https://www.visitscotland.org/tourism-events-industry/visitor-levy'],None,None,'Early engagement only, no formal consultation.'),
('Cardiff','Wales','£1.30 per person per night (75p shared hostel/dorm rooms and tent pitches)','1 Apr 2027 (account for bookings from 28 Sep 2026)','confirmed',['https://www.gov.wales/check-if-local-council-charges-visitor-levy-wales','https://www.gov.wales/visitor-levy-for-visitor-accommodation-providers-overview'],51.481,-3.179,''),
